#!/usr/bin/env python3

import sympy as sm
from sympy import Matrix, zeros, eye

def test_edge_cases():
    """Test various edge cases for col_insert"""
    print("Testing edge cases for col_insert...")

    test_cases = [
        {
            "name": "Insert single column at start",
            "matrix": eye(3),
            "insert": Matrix([1, 2, 3]),
            "pos": 0,
            "expected_shape": (3, 4)
        },
        {
            "name": "Insert single column at end",
            "matrix": eye(3), 
            "insert": Matrix([1, 2, 3]),
            "pos": 3,
            "expected_shape": (3, 4)
        },
        {
            "name": "Insert multiple columns in middle",
            "matrix": Matrix([[1, 2, 3], [4, 5, 6]]),
            "insert": Matrix([[0, 0], [0, 0]]),
            "pos": 1,
            "expected_shape": (2, 5)
        },
        {
            "name": "Negative position (from end)",
            "matrix": eye(3),
            "insert": Matrix([9, 9, 9]),
            "pos": -1,
            "expected_shape": (3, 4)
        },
        {
            "name": "Insert wider matrix",
            "matrix": eye(2),
            "insert": zeros(2, 3),
            "pos": 1,
            "expected_shape": (2, 5)
        }
    ]

    all_passed = True

    for case in test_cases:
        print(f"\n  Testing: {case['name']}")

        try:
            result = case["matrix"].col_insert(case["pos"], case["insert"])

            if result.shape != case["expected_shape"]:
                print(f"    ✗ Shape mismatch: got {result.shape}, expected {case['expected_shape']}")
                all_passed = False
            else:
                print(f"    ✓ Shape correct: {result.shape}")

            # Verify the structural integrity
            matrix = case["matrix"]
            insert = case["insert"]
            pos = case["pos"]

            # Normalize negative position
            if pos < 0:
                pos = matrix.cols + pos + 1

            # Check left part
            for i in range(matrix.rows):
                for j in range(min(pos, matrix.cols)):
                    if result[i, j] != matrix[i, j]:
                        print(f"    ✗ Left part error at [{i},{j}]: got {result[i,j]}, expected {matrix[i,j]}")
                        all_passed = False

            # Check inserted part
            for i in range(insert.rows):
                for j in range(insert.cols):
                    result_j = pos + j
                    if result[i, result_j] != insert[i, j]:
                        print(f"    ✗ Insert part error at [{i},{result_j}]: got {result[i,result_j]}, expected {insert[i,j]}")
                        all_passed = False

            # Check right part
            for i in range(matrix.rows):
                for j in range(pos, matrix.cols):
                    result_j = j + insert.cols
                    if result_j < result.cols and result[i, result_j] != matrix[i, j]:
                        print(f"    ✗ Right part error at [{i},{result_j}]: got {result[i,result_j]}, expected {matrix[i,j]}")
                        all_passed = False

            if result.shape == case["expected_shape"]:
                print(f"    ✓ Structure verification passed")

        except Exception as e:
            print(f"    ✗ Exception: {e}")
            all_passed = False

    return all_passed

if __name__ == "__main__":
    success = test_edge_cases()

    print(f"\n{'='*60}")
    if success:
        print("ALL EDGE CASE TESTS PASSED! ✓")
    else:
        print("SOME EDGE CASE TESTS FAILED! ✗")

